{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "IAM policy attached directly to user instead of group or role",
      "resource": "aws_iam_user_policy_attachment.privesc3-passrole-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "Attaching IAM policies directly to users violates the principle of least privilege and access management best practices, making it difficult to audit permissions and increasing the risk of retaining excessive privileges if the user's role changes."
    }
  ],
  "patched_code": "resource "aws_iam_group" "privesc3-passrole-group" {
  name = "privesc3-passrole-group"
}

resource "aws_iam_group_policy_attachment" "privesc3-passrole-group-attach-policy" {
  group      = aws_iam_group.privesc3-passrole-group.name
  policy_arn = aws_iam_policy.fn1-passrole-star.arn
}

resource "aws_iam_user_group_membership" "privesc3-passrole-user-membership" {
  user = aws_iam_user.fn1-privesc3-partial-user.name
  groups = [
    aws_iam_group.privesc3-passrole-group.name
  ]
}",
  "fix_summary": "Replaced the direct user policy attachment with a group-based approach: created an IAM group, attached the policy to the group, and added the user to that group. This aligns with AWS security best practices for managing IAM permissions."
}
